interface Greeter {
    void greet();

    default void greetThree() {
        greet();
        greet();
        greet();
    }
}

class Robot implements Greeter {
    public void greet() {
        System.out.println("嘀嘀");
    }
}

public class Main {
    public static void main(String[] args) {
        Greeter g = new Robot();
        g.greetThree();
    }
}

interface Speaker {
    void speak();
}

class Cat implements Speaker {
    public void speak() {
        System.out.println("小橘：喵～");
    }
}

class Robot implements Speaker {
    public void speak() {
        System.out.println("铁喵：嘀嘀");
    }
}

public class Main {
    public static void main(String[] args) {
        Speaker[] crowd = { new Cat(), new Robot() };
        for (Speaker s : crowd) {
            s.speak();
        }
    }
}
